    for i in range(n):
        val[i] = int(data[1 + 4 * i])
        left[i] = int(data[2 + 4 * i])
        sib[i] = int(data[3 + 4 * i])
        par[i] = int(data[4 + 4 * i])
    out = []
    cur = 0
    while cur != -1:
        out.append(val[cur])
        if left[cur] != -1:
            cur = left[cur]
        else:
            while cur != -1 and sib[cur] == -1:
