def gen(rng):
    def build(n, vals, pick_parent):
        # node 0 is the root; other labels are shuffled so labels do not follow preorder
        labels = list(range(1, n))
        rng.shuffle(labels)
        labels = [0] + labels
        depth = [0] * n
        children = [[] for _ in range(n)]
        parent = [-1] * n
        for i in range(1, n):
            p = pick_parent(i, depth)
            depth[i] = depth[p] + 1
            children[p].append(i)
            parent[i] = p
        left = [-1] * n; sib = [-1] * n; par = [-1] * n
        for p in range(n):
            ch = children[p]
            rng.shuffle(ch)
            if ch:
                left[labels[p]] = labels[ch[0]]
            for a, b in zip(ch, ch[1:]):
                sib[labels[a]] = labels[b]
            for c in ch:
                par[labels[c]] = labels[p]
        v = [0] * n
        for i in range(n):
            v[labels[i]] = vals[i]
        lines = [str(n)]
        for u in range(n):
            lines.append(f'{v[u]} {left[u]} {sib[u]} {par[u]}')
        return '\n'.join(lines)
    def rv(n, lo=-10**9, hi=10**9):
        return [rng.randint(lo, hi) for _ in range(n)]
    tests = [build(1, [7], None) if False else '1\n7 -1 -1 -1']
    tests.append(build(2, [1, 2], lambda i, d: 0))
    tests.append(build(6, [1, 1, 1, 1, 1, 1], lambda i, d: rng.randrange(i)))
    tests.append(build(7, rv(7, -5, 5), lambda i, d: i - 1))
    tests.append(build(7, rv(7, -5, 5), lambda i, d: 0))
    for n in (3, 4, 5, 8, 10, 15, 20, 25):
        for _ in range(2):
            tests.append(build(n, rv(n, -20, 20), lambda i, d: rng.randrange(i)))
    for n in (12, 20):
        tests.append(build(n, rv(n, -20, 20), lambda i, d: max(0, i - rng.randint(1, 2))))
    N = 100000
    tests.append(build(N, rv(N), lambda i, d: rng.randrange(i)))
    tests.append(build(N, rv(N), lambda i, d: 0))
    # deep: a chain of 4999 edges (depth 4999) with everything else hanging off it
    def deep(i, d):
        if i < 5000:
            return i - 1
        return rng.randrange(5000)
    tests.append(build(N, rv(N), deep))
    def deepish(i, d):
        while True:
            p = max(0, i - rng.randint(1, 40))
            if d[p] < 4999:
                return p
    tests.append(build(N, rv(N), deepish))
    return tests

